from rdkit import Chem
from rdkit.Chem import AllChem
from rdkit.Chem.rdMolDescriptors import CalcMolFormula
import numpy as np

rw = Chem.RWMol()
idx = {}
def add(sym, name):
    i = rw.AddAtom(Chem.Atom(sym)); idx[name]=i; return i

add("Cl","Cl"); add("Ru","Ru"); add("P","P1"); add("P","P2"); add("N","N")
# backbone CH2: P1-CH2-CH2-N and N-CH2-CH2-P2
add("C","C5"); add("C","C6"); add("C","C9"); add("C","C10")
# tBu groups: 2 per P
tbu = {}
for k,p in enumerate(("P1","P2")):
    for q in range(2):
        cq = add("C", f"Q{p}{q}")
        me = [add("C", f"M{p}{q}{m}") for m in range(3)]
        tbu[(p,q)] = (cq, me)
# hydrogens
h_ch2 = {}
for c in ("C5","C6","C9","C10"):
    h_ch2[c] = [add("H", f"H{c}{m}") for m in range(2)]
h_me = {}
for key,(cq,me) in tbu.items():
    for m in me:
        h_me[m] = [add("H", f"H{m}{j}") for j in range(3)]

B = Chem.BondType.SINGLE
def bond(a,b): rw.AddBond(idx[a], idx[b], B)
bond("Cl","Ru"); bond("Ru","P1"); bond("Ru","P2"); bond("Ru","N")
bond("P1","C5"); bond("C5","C6"); bond("C6","N"); bond("N","C9"); bond("C9","C10"); bond("C10","P2")
for p in ("P1","P2"):
    for q in range(2):
        cq, me = tbu[(p,q)]
        rw.AddBond(idx[p], cq, B)
        for m in me: rw.AddBond(cq, m, B)
for c,hs in h_ch2.items():
    for h in hs: rw.AddBond(idx[c], h, B)
for m,hs in h_me.items():
    for h in hs: rw.AddBond(m, h, B)
for a in rw.GetAtoms(): a.SetNoImplicit(True)
mol = rw.GetMol()
Chem.SanitizeMol(mol)
print("formula:", CalcMolFormula(mol), "natoms:", mol.GetNumAtoms())
ok = AllChem.EmbedMolecule(mol, randomSeed=11, useRandomCoords=True)
print("embed:", ok)
Chem.MolToXYZFile(mol, "initial3.xyz")
# index map for constraints
order = [a.GetSymbol() for a in mol.GetAtoms()]
print("Ru idx:", idx["Ru"], "P1:", idx["P1"], "P2:", idx["P2"], "N:", idx["N"], "Cl:", idx["Cl"])
